begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;select no_plan();
select ok(not has_table_privilege('authenticated','public.expenses','INSERT,UPDATE,DELETE'),'Expenses cannot be directly written');
select ok(not has_table_privilege('authenticated','public.expense_evidence','INSERT,UPDATE,DELETE'),'Evidence links are trusted append only');
select ok(not has_function_privilege('authenticated','private.post_expense(uuid,integer,jsonb)','EXECUTE'),'Expense kernel is private');
select ok(not has_function_privilege('authenticated','public.attach_expense_receipt(jsonb,uuid,uuid,integer,text,integer,text)','EXECUTE'),'Trusted byte validation cannot be bypassed');
select ok((select proowner='carrier_finance'::regrole and prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.post_expense(uuid,integer,jsonb)'::regprocedure),'Restricted expense owner and pinned path');
select ok(not has_table_privilege('carrier_finance','public.expenses','UPDATE,DELETE'),'Finance cannot mutate confirmed expense');
select ok(not has_table_privilege('carrier_security','public.journal_lines','INSERT'),'Evidence/command role has no journal writes');
select ok(not has_table_privilege('authenticated','storage.objects','INSERT') or not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and cmd='INSERT' and roles @> array['authenticated']::name[]),'No ordinary upload policy');
select ok(not pg_has_role('postgres','carrier_finance','SET') and not pg_has_role('postgres','carrier_security','SET'),'Temporary role membership revoked');
select ok(not has_schema_privilege('carrier_finance','public','CREATE') and not has_schema_privilege('carrier_security','public','CREATE'),'No schema write privilege remains');
select ok((select not public and file_size_limit=5242880 from storage.buckets where id='receipts'),'Private 5MB receipt bucket');
select set_config('request.jwt.claims','{}',true);set local role authenticated;
select throws_ok($$select public.post_financial_event('EXPENSE',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Expense requires live staff');
select throws_ok($$select public.post_financial_event('REIMBURSEMENT',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Reimbursement requires live staff');
select throws_ok($$select public.post_financial_event('EXPENSE_RECOVERY',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Expense recovery requires live staff');
select throws_ok($$select public.post_financial_event('EXPENSE_OFFSET',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Expense offset requires live staff');
select throws_ok($$select public.get_expense_claims(gen_random_uuid())$$,'42501','FORBIDDEN','Hidden expense claims denied');
reset role;select * from finish();rollback;
